function clamp(x,a,b){ return Math.min(b, Math.max(a,x)); }
function logistic(x){ return 1/(1+Math.exp(-x)); }

/* ============ formatting ============ */
function fmtUSD(x, dec){
  if (x == null || isNaN(x)) return "—";
  var a = Math.abs(x);
  if (a >= 1e9) return "$" + (x/1e9).toFixed(2) + "B";
  if (a >= 1e6) return "$" + (x/1e6).toFixed(dec != null ? dec : 1) + "M";
  if (a >= 1e3) return "$" + (x/1e3).toFixed(1) + "k";
  return "$" + x.toFixed(0);
}
function fmtUSDfull(x){
  if (x == null || isNaN(x)) return "—";
  var s = Math.abs(x).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return (x < 0 ? "-$" : "$") + s;
}
function fmtPct(x, dec){ return (x*100).toFixed(dec != null ? dec : 1) + "%"; }
function fmtSigned(x){ return (x >= 0 ? "+" : "−") + "$" + Math.abs(x).toFixed(0); }
function esc(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;"); }

