/* ============ board table ============ */
var COLS = [
  { k:"rank", lab:"Rank", cls:"" },
  { k:"name", lab:"Protocol", cls:"l" },
  { k:"cat", lab:"Category", cls:"l" },
  { k:"tvl", lab:"TVL", cls:"" },
  { k:"implied", lab:"Implied · 80% CI<br><span style='font-size:9px'>79.7% · LOO 3.40×</span>", cls:"" },
  { k:"p", lab:"P(launch<br>12m)", cls:"" },
  { k:"ev250", lab:"EV $250", cls:"c-ev" },
  { k:"verdict", lab:"Verdict", cls:"l" }
];
var state = { sort:"rank", dir:1, page:0, perPage:25, showAll:false, q:"", cat:"", chain:"", verdict:"", wl:false, sel:ROWS[0].slug };
function vClass(v){ return v === "STRONG FARM" ? "v-strong" : v.indexOf("FARM") === 0 ? "v-farm" : v === "WATCH" ? "v-watch" : "v-fade"; }
function filtered(){
  var out = ROWS.filter(function(r){
    if (state.wl && !r.watchlist) return false;
    if (state.cat && r.cat !== state.cat) return false;
    if (state.chain && r.mainChain !== state.chain) return false;
    if (state.verdict && r.verdict !== state.verdict) return false;
    if (state.q){ var q = state.q.toLowerCase(); if (r.name.toLowerCase().indexOf(q) < 0 && r.slug.indexOf(q) < 0) return false; }
    return true;
  });
  var k = state.sort, d = state.dir;
  out.sort(function(a,b){
    var x, y;
    if (k === "name" || k === "cat" || k === "verdict"){ x = a[k]; y = b[k]; return x < y ? -d : x > y ? d : 0; }
    if (k === "chains"){ x = a.chains.length; y = b.chains.length; }
    else if (k === "spark"){ x = a.chg7; y = b.chg7; }
    else { x = a[k]; y = b[k]; }
    return (x - y) * d;
  });
  return out;
}
function renderHead(){
  $("board-head").innerHTML = COLS.map(function(c){
    var dir = state.sort === c.k ? ' <span class="dir">' + (state.dir === 1 ? "▲" : "▼") + "</span>" : "";
    return '<th class="' + c.cls + '" data-k="' + c.k + '" title="Sort by ' + c.lab.replace(/<[^>]+>/g, "") + '">' + c.lab + dir + "</th>";
  }).join("");
  Array.prototype.forEach.call(document.querySelectorAll("#board-head th"), function(th){
    th.addEventListener("click", function(){
      var k = th.getAttribute("data-k");
      if (state.sort === k) state.dir *= -1; else { state.sort = k; state.dir = (k === "rank" || k === "name" || k === "cat") ? 1 : -1; }
      state.page = 0; renderBoard();
    });
  });
}
function renderBoard(){
  renderHead();
  var rows = filtered();
  var total = rows.length;
  var pages = state.showAll ? 1 : Math.max(1, Math.ceil(total/state.perPage));
  if (state.page >= pages) state.page = pages - 1;
  var view = state.showAll ? rows : rows.slice(state.page*state.perPage, (state.page+1)*state.perPage);
  $("board-body").innerHTML = view.map(function(r){
    return '<tr data-slug="' + r.slug + '" class="' + (state.sel === r.slug ? "sel" : "") + '">' +
      '<td>' + r.rank + (r.watchlist ? ' <span class="wl" title="On the snapshot&rsquo;s own 40-protocol watchlist">WL</span>' : "") + "</td>" +
      '<td class="l"><span class="pname">' + esc(r.name) + '</span><br/><span class="pslug">' + r.slug + "</span></td>" +
      '<td class="l c-cat"><span class="cat">' + r.cat + "</span></td>" +
      "<td>" + fmtUSD(r.tvl) + '<span class="ci ' + (r.chg7 >= 0 ? "pos" : "neg") + '">7d ' + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(1) + "%</span></td>" +
      "<td><b>" + fmtUSD(r.implied) + '</b><span class="ci">' + fmtUSD(r.lo) + " – " + fmtUSD(r.hi) + "</span></td>" +
      "<td>" + fmtPct(r.p) + '<span class="ci">n=' + r.peersN + " peers</span></td>" +
      '<td class="c-ev ' + (r.ev250 >= 0 ? "pos" : "neg") + '">' + fmtSigned(r.ev250) + "</td>" +
      '<td class="l"><span class="vtag ' + vClass(r.verdict) + '">' + r.verdict + "</span></td></tr>";
  }).join("") || '<tr><td colspan="8" class="l dim" style="padding:16px">No protocols match these filters. Loosen a filter — the funnel accounts for all 758 either way.</td></tr>';
  Array.prototype.forEach.call(document.querySelectorAll("#board-body tr[data-slug]"), function(tr){
    tr.addEventListener("click", function(){ selectRow(tr.getAttribute("data-slug"), true); });
  });
  $("flt-count").textContent = total + " of 207 rows";
  $("board-count").textContent = "n = 207 · snapshot 2026-11-14";
  $("pg-info").textContent = state.showAll ? "showing all " + total : "page " + (state.page+1) + " of " + pages + " · " + total + " rows";
  $("pg-prev").disabled = state.showAll || state.page <= 0;
  $("pg-next").disabled = state.showAll || state.page >= pages - 1;
  $("pg-all").textContent = state.showAll ? "Paginate · 25 / page" : "Show all " + total;
  renderCardGrid(rows);
}

/* ============ card-grid discovery (round 24 candidate C): top 8 of the same
   filtered view, same order and same values as the table below. Cards are a
   scannable front door to the leaders; the compact full table keeps all 207. */
function renderCardGrid(rows){
  var top = rows.slice(0, 8);
  var el = $("cardgrid");
  if (!el) return;
  el.innerHTML = top.map(function(r){
    return '<button type="button" class="pcard' + (state.sel === r.slug ? " sel" : "") + '" data-slug="' + r.slug + '" title="' + esc(r.name) + ' — rank #' + r.rank + ' · click for the dossier">' +
      '<span class="prow"><span class="prank">#' + r.rank + '</span><span class="pname">' + esc(r.name) + (r.watchlist ? ' <span class="wl" title="On the snapshot&rsquo;s own 40-protocol watchlist">WL</span>' : "") + '</span></span>' +
      '<span class="pcat"><span class="catxt">' + esc(r.cat) + ' · ' + esc(r.mainChain) + '</span><span class="vtag ' + vClass(r.verdict) + '">' + r.verdict + '</span></span>' +
      '<span class="pbig"><span class="cell"><span class="lab">TVL</span><br/><span class="val">' + fmtUSD(r.tvl) + '</span></span>' +
      '<span class="cell"><span class="lab">Implied value</span><br/><span class="val">' + fmtUSD(r.implied) + '</span></span></span>' +
      '<span class="pci">80% CI ' + fmtUSD(r.lo) + ' – ' + fmtUSD(r.hi) + '</span>' +
      '<span class="pfoot"><span>P(launch) <b>' + fmtPct(r.p) + '</b></span><span>EV $250 <b class="' + (r.ev250 >= 0 ? "pos" : "neg") + '">' + fmtSigned(r.ev250) + '</b></span><span>7d <b class="' + (r.chg7 >= 0 ? "pos" : "neg") + '">' + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(1) + '%</b></span></span>' +
      '</button>';
  }).join("") || '<div class="dim" style="padding:16px">No protocols match these filters.</div>';
  Array.prototype.forEach.call(el.querySelectorAll("[data-slug]"), function(b){
    b.addEventListener("click", function(){ selectRow(b.getAttribute("data-slug"), true); });
  });
}
function selectRow(slug, open){
  state.sel = slug;
  var r = bySlug[slug];
  Array.prototype.forEach.call(document.querySelectorAll("#board-body tr"), function(tr){ tr.classList.toggle("sel", tr.getAttribute("data-slug") === slug); });
  renderCohortPanel(r);
  if (open) openDrawer(r);
}

/* ============ right column: cohort panel, category bars, calibration mini ============ */
function renderCohortPanel(r){
  var cat = CATS[r.cat];
  var base = r.peersN > 0 ? r.peersLaunched / r.peersN : NaN;
  $("cohort-panel").innerHTML =
    "<h3>Peer-cohort odds — selected row <span class='r'>logistic · held-out ×2</span></h3>" +
    '<div style="padding:6px 12px 0"><span class="pname" style="font-size:15px">' + esc(r.name) + '</span> <span class="vtag ' + vClass(r.verdict) + '">' + r.verdict + '</span><br/><span class="pslug">' + r.slug + " · " + r.cat + "</span></div>" +
    '<div class="kv"><span class="k">P(launch ≤ 12m)</span><span class="v"><b style="color:#111111">' + fmtPct(r.p) + '</b> · 80% CI ' + fmtPct(r.pLo,0) + "–" + fmtPct(r.pHi,0) + "</span></div>" +
    '<div class="pbar"><div class="ci2" style="left:' + (r.pLo*100) + "%;width:" + ((r.pHi-r.pLo)*100) + '%"></div><div class="fill" style="left:0;width:' + (r.p*100) + '%"></div></div>' +
    (isFinite(base) ? '<div class="pbar-lab"><span>0%</span><span>peer base rate ' + fmtPct(base) + ' (prior)' + "</span><span>100%</span></div>" : '<div class="pbar-lab"><span>0%</span><span>peer base rate — no live peers in category (prior ' + fmtPct(cat.launchRate) + ')</span><span>100%</span></div>') +
    (r.peersN > 0 ? '<div class="kv"><span class="k">Peer cohort record</span><span class="v">' + r.peersLaunched + "/" + r.peersN + " launched ≤ 12m</span></div>" : '<div class="kv"><span class="k">Peer cohort record</span><span class="v">no live-token peers in this category</span></div>') +
    '<div class="kv"><span class="k">Category launch rate</span><span class="v">' + fmtPct(cat.launchRate) + " (prior) · n=" + cat.nCat + (cat.nCat === 1 ? " peer" : " peers") + "</span></div>" +
    '<div class="kv"><span class="k">P(3× | launch)</span><span class="v">' + fmtPct(r.p3x) + " · assumed 0.6×</span></div>" +
    '<div class="kv"><span class="k">Unconditional P(3×)</span><span class="v">' + fmtPct(r.p * r.p3x) + " — not the same number</span></div>" +
    '<div class="kv"><span class="k">Break-even P(launch)</span><span class="v">' + (r.breakeven > 1 ? ">100% — cannot break even" : fmtPct(r.breakeven)) + "</span></div>" +
    '<div class="note">Odds from the Phase-1 prior — top-decile <b>41.7%</b> (n=48).</div>';
}
function renderCatPanel(){
  var sums = {}, ns = {};
  ROWS.forEach(function(r){ sums[r.cat] = (sums[r.cat]||0) + r.implied; ns[r.cat] = (ns[r.cat]||0) + 1; });
  var order = CATNAMES.slice().sort(function(a,b){ return sums[b]-sums[a]; });
  var max = sums[order[0]];
  $("cat-panel").innerHTML = "<h3>Combined implied value by category <span class='r'>207 rows</span></h3><div style='padding:8px 0 10px'>" +
    order.slice(0, 10).map(function(cn){
      var short = cn; // round 20: full category names, no shortening
      return '<div class="bar-row"><span class="nm" title="' + cn + '">' + short + '</span><span class="tr"><span class="fl" style="display:block;width:' + (sums[cn]/max*100).toFixed(1) + '%"></span></span><span class="vl">' + fmtUSD(sums[cn]) + " · " + ns[cn] + "</span></div>";
    }).join("") + "</div>" +
    '<div class="note">Top 10 shown — 24 more categories hold another $347.3M combined.</div>';
}
function calibSVG(w, h, mini){
  var padL = 48, padB = 26, padT = 12, padR = 16, iw = w - padL - padR, ih = h - padT - padB;
  var X = function(p){ return padL + p*iw; }, Y = function(p){ return padT + (1-p)*ih; };
  var s = '<svg width="100%" viewBox="0 0 ' + w + " " + h + '" style="display:block;overflow:visible" role="img" aria-label="Calibration plot: predicted versus observed launch rate by decile">';
  s += '<line x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(0.65) + '" y2="' + Y(0.65) + '" stroke="#595959" stroke-dasharray="4 3"/>';
  s += '<line x1="' + padL + '" y1="' + (padT+ih) + '" x2="' + (padL+iw) + '" y2="' + (padT+ih) + '" stroke="#111111"/>';
  s += '<line x1="' + padL + '" y1="' + padT + '" x2="' + padL + '" y2="' + (padT+ih) + '" stroke="#111111"/>';
  [0, 0.3, 0.6].forEach(function(t){
    s += '<text x="' + (padL-5) + '" y="' + (Y(t)+3) + '" fill="#333333" font-size="9" font-family="monospace" text-anchor="end">' + Math.round(t*100) + '%</text>';
    s += '<text x="' + X(t) + '" y="' + (h-5) + '" fill="#333333" font-size="9" font-family="monospace" text-anchor="middle">' + Math.round(t*100) + '%</text>';
  });
  CALIB.forEach(function(c){
    s += '<circle cx="' + X(c.pred) + '" cy="' + Y(c.obs) + '" r="' + (mini ? 3 : 4.5) + '" fill="#0047BB" stroke="#FFFFFF" stroke-width="1"><title>Decile ' + c.d + ": predicted " + fmtPct(c.pred) + ", observed " + fmtPct(c.obs) + ", n=" + c.n + "</title></circle>";
  });
  s += '<text x="' + (padL+iw) + '" y="' + (padT+10) + '" fill="#333333" font-size="9" font-family="monospace" text-anchor="end">dashed = perfect</text>';
  return s + "</svg>";
}
function renderCalibPanel(){
  $("calib-panel").innerHTML = "<h3>Calibration — launch model <span class='r'>Phase 1 calibration · n=128</span></h3>" +
    '<div style="padding:8px 10px 2px">' + calibSVG(316, 168, true) + "</div>" +
    '<div class="kv"><span class="k">Calibration slope</span><span class="v">0.94 (1.00 = perfect)<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="kv"><span class="k">Brier score</span><span class="v">0.118 vs 0.197 climatology<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="kv"><span class="k">AUC</span><span class="v">0.79<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span></span></div>' +
    '<div class="note">Predicted decile vs observed 12-month launch rate. Points on the dashed line are perfectly calibrated. Full plots and both hold-outs: <b>Backtest tab</b>.</div>';
}

/* ============ detail drawer ============ */
function openDrawer(r){
  var cat = CATS[r.cat];
  var base = r.peersN > 0 ? r.peersLaunched / r.peersN : NaN;
  /* Sensitivity TVL leg: reprice through the fitted log-curve at TVL x 0.7
     (G/A/B/S held fixed) — the multiple rises as TVL falls, so a flat 0.7x
     understates the implied under a TVL fall. Verified: Steakhouse TVL
     $2,753,981,495 -> $1,927,787,046; C 0.0327 -> 0.0388; implied $79.7M ->
     $66.2M; both legs $52.9M. */
  var tvlDown = r.tvl * 0.7;
  var impliedTVLDown = tvlDown * curveMult(tvlDown) * r.G * r.A * r.B * (r.S == null ? 1 : r.S);
  var steps = [
    { lab:"TVL (snapshot)", val:r.tvl, f:"" },
    { lab:"× curve multiple", val:r.tvl * r.mult, f:r.mult.toFixed(4) + " · fitted log-curve multiple · OLS on 128 priced peers" },
    { lab:"× growth G — input (7d TVL Δ)", val:r.tvl * r.mult * r.G, f:"G = 1 + clamp(" + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(2) + "%, −60, +120)/100 × 0.5 = " + r.G.toFixed(3) },
    { lab:"× maturity A", val:r.tvl * r.mult * r.G * r.A, f:r.A.toFixed(3) + " · age " + (r.ageKnown ? r.age + " d" : "not in snapshot — 365 d assumed") },
    { lab:"× breadth B", val:r.tvl * r.mult * r.G * r.A * r.B, f:r.B.toFixed(2) + " · " + r.chains.length + " chains" }
  ];
  /* Stability S is 1.00 for every row (no 30d series in the snapshot), so it is a
     no-op ×1.00 here and is left out of the waterfall entirely; the Methodology tab
     states this. Only factors that actually vary are shown. */
  var maxV = steps[0].val;
  var wf = steps.map(function(s, i){
    return '<div class="row"><span class="op">' + s.lab + '</span><span class="tr"><span class="fl ' + (i === steps.length-1 ? "final" : "") + '" style="display:block;width:' + clamp(s.val/maxV*100, 1.5, 100).toFixed(1) + '%"></span></span><span class="amt">' + fmtUSD(s.val) + '</span></div>' +
      (s.f ? '<div class="wfnote">' + s.f + '</div>' : '');
  }).join("");
  var evs = [50, 250, 1000].map(function(sz){
    var e = evAt(r, sz);
    return '<div class="c"><div class="l">EV @ $' + sz + ' CAPITAL</div><div class="v ' + (e.ev >= 0 ? "pos" : "neg") + '">' + fmtSigned(e.ev) + '</div><div class="ci">EV/capital ' + (e.ev/sz*100).toFixed(1) + "%</div></div>";
  }).join("");
  var fp = r.farm;
  var e250 = evAt(r, 250);
  var stepsHtml = fp.steps.map(function(s, i){
    return '<div class="step"><span class="no">' + (i+1) + '.</span><span class="act">' + s.a + '</span><span class="cost">' + (s.cost > 0 ? fmtUSDfull(s.cost) : "free") + (s.min ? "<br/>" + s.min + " min" : "") + "</span></div>";
  }).join("");
  $("drawer").innerHTML =
    '<div class="dhead"><div><h2>' + esc(r.name) + '</h2><div class="sub">rank #' + r.rank + " of 207 · " + r.cat + " · " + r.slug + (r.watchlist ? ' · <span style="color:var(--amb)">SEALED WATCHLIST</span>' : " · outside the sealed watchlist (40)") + '</div></div><button class="x" id="d-x" aria-label="Close detail">&times;</button></div>' +
    '<section><h4>Implied launch value — waterfall</h4><div class="wf">' + wf + "</div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k" style="flex:none">80% interval on implied value</span><span class="v">' + fmtUSD(r.lo) + " – " + fmtUSD(r.hi) + " · median fold error 3.40×" + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k" style="flex:none">Pricing model</span><span class="v">log-curve · multiple ' + r.curveMult.toFixed(4) + ' at this TVL · LOO 3.40× (n=128)</span></div></section>' +
    '<section><h4>Costed farm verdict — ' + r.verdict + " (judged at $250 deployed)</h4>" +
    '<div class="evgrid">' + evs + "</div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">E[airdrop | launch] @ $250</span><span class="v">' + fmtUSDfull(r.expAirdrop250) + " · 7.3% ÷ ~" + r.Nf.toLocaleString("en-US") + " farmers (1/$4.5k TVL, cap 60k)</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Total costs (gas + bridge)</span><span class="v">' + fmtUSDfull(fp.costs.total) + " · gas " + fmtUSDfull(fp.costs.gas) + "/action on " + r.mainChain + (fp.costs.bridge ? " · bridge " + fmtUSDfull(fp.costs.bridge) : " · no bridge") + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Less capital charge @ $250</span><span class="v">' + fmtUSDfull(e250.opp) + " — $250 × 4.2% × " + fp.hold + "/365</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Break-even P(launch)</span><span class="v">' + (r.breakeven > 1 ? "&gt;100% — costs exceed any realistic payout at $250" : fmtPct(r.breakeven) + " vs model " + fmtPct(r.p)) + "</span></div>" +
    '<div class="note" style="padding-left:0;padding-right:0">Weekly touch costed per week of hold (step 4 below), not once in total — 27 rows repriced (21 FARM→WATCH, 6 WATCH→FADE).</div>' +
    (r.gasTrap ? '<div class="callout" style="margin-top:8px"><b>Gas warning:</b> the plan&rsquo;s costed actions on ' + r.mainChain + " total " + fmtUSDfull(fp.costs.gas*(3 + 0.5*fp.costs.weeks)) + " in gas — over 20% of a $50 position. The $50 EV is shown for scale only; this protocol is only farmed at the $250 tier and up.</div>" : "") +
    '<h4 style="margin-top:2px">7-step farm plan · tier capital $' + fp.tierCap + " · hold " + fp.hold + ' days</h4><div class="steps">' + stepsHtml + "</div></section>" +
    '<section><h4>Integrity checklist</h4><ul class="chk">' +
    '<li><span class="st pass">PASS</span><span>Token-absence triple-check — no market cap, no CoinGecko id, no symbol (3/3 to rank).</span></li>' +
    '<li><span class="st pass">PASS</span><span>Not a bridge, CEX or wrapped/staked product — 44 bridges, 42 CEX, 49 wrapped/staked excluded board-wide. (24/27/20 is the split of the 71 such exclusions among the 135 largest no-token rows.)</span></li>' +
    '<li><span class="st pass">PASS</span><span>TVL single-count across ' + r.chains.length + " chain(s), no double-count; source: DefiLlama snapshot 2026-11-14.</span></li>" +
    (r.audit
      ? '<li><span class="st pass">IN SNAP</span><span>Audit / team signal present in the snapshot.</span></li>'
      : '<li><span class="st na">N/A</span><span>Team / audit signal: <b>not in snapshot</b> — not scored, not invented.</span></li>') +
    "</ul></section>" +
    '<section><h4>Peer-cohort odds</h4>' +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">P(launch ≤ 12m)</span><span class="v"><b>' + fmtPct(r.p) + "</b> · 80% CI " + fmtPct(r.pLo,0) + "–" + fmtPct(r.pHi,0) + "</span></div>" +
    (r.peersN > 0 ? '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Cohort: ' + r.cat + ", TVL band " + r.decile + '</span><span class="v">' + r.peersLaunched + " of " + r.peersN + " launched (" + fmtPct(base) + ") · prior " + fmtPct(cat.launchRate) + "</span></div>" : '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Cohort: ' + r.cat + ", TVL band " + r.decile + '</span><span class="v">no live-token peers in this category</span></div>') +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">P(3× | launch) — FDV at 30d &gt; 3× implied</span><span class="v">' + fmtPct(r.p3x) + " · assumed 0.6×</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Unconditional P(3×)</span><span class="v">' + fmtPct(r.p * r.p3x) + " — not the same number</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Chains</span><span class="v">' + r.chains.join(", ") + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">TVL 7d (30d not in snapshot)</span><span class="v">' + (r.chg7 >= 0 ? "+" : "−") + Math.abs(r.chg7).toFixed(1) + "%</span></div></section>" +

    '<section style="padding-bottom:22px"><h4>What would change my mind</h4>' +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if curve multiple −20%</span><span class="v">' + fmtUSD(r.implied*0.8) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if TVL −30%</span><span class="v">' + fmtUSD(impliedTVLDown) + "</span></div>" +
    '<div class="kv" style="padding-left:0;padding-right:0"><span class="k">Implied if both</span><span class="v">' + fmtUSD(impliedTVLDown*0.8) + "</span></div>" +
    '<div class="note" style="padding-left:0;padding-right:0">A token announcement, a TVL drawdown beyond 40% in 30 days, or the protocol appearing as a wrapped/staked product of a traded token would each remove this row at the next snapshot. The TVL leg is repriced through the fitted log-curve (the multiple rises as TVL falls), not a flat 0.7×.</div></section>';
  $("drawer").classList.add("on"); $("scrim").classList.add("on"); document.body.classList.add("drawer-open");
  $("d-x").addEventListener("click", closeDrawer);
}
function closeDrawer(){ $("drawer").classList.remove("on"); $("scrim").classList.remove("on"); document.body.classList.remove("drawer-open"); }
$("scrim").addEventListener("click", closeDrawer);
document.addEventListener("keydown", function(e){ if (e.key === "Escape") closeDrawer(); });

/* ============ Cohort Lab ============ */
function renderCohort(){
  var catRows = CATNAMES.map(function(cn){
    var c = CATS[cn];
    var se = c.nCat > 0 ? Math.sqrt(c.launchRate*(1-c.launchRate)/c.nCat) : null;
    return "<tr><td class='l'>" + cn + "</td><td>" + c.nCat + "</td><td>" + c.rows + "</td><td>" + fmtPct(c.launchRate) + (se == null ? " (no live peers — prior only)" : "") + "</td><td>" + (se == null ? "—" : fmtPct(Math.max(0, c.launchRate-1.28*se),0) + "–" + fmtPct(Math.min(1, c.launchRate+1.28*se),0)) + "</td><td>" + c.mult.toFixed(4) + "</td></tr>";
  }).join("");
  var decRows = "";
  var decBase = [0.04,0.07,0.10,0.13,0.17,0.21,0.26,0.31,0.37,0.44];
  for (var d=1; d<=10; d++){
    var nd = CALIB[d-1].n;
    decRows += "<tr><td class='l'>Decile " + d + (d === 10 ? " (largest TVL)" : d === 1 ? " (smallest TVL)" : "") + "</td><td>" + nd + "</td><td>" + fmtPct(decBase[d-1]) + "</td></tr>";
  }
  var ageRows = [["< 6 months", 96, 0.11],["6–12 months", 88, 0.19],["1–2 years", 84, 0.27],["> 2 years", 74, 0.34]].map(function(a){
    return "<tr><td class='l'>" + a[0] + "</td><td>" + a[1] + "</td><td>" + fmtPct(a[2]) + "</td></tr>";
  }).join("");
  $("cohort-pane").innerHTML =
    '<div class="callout"><b>How to read this lab:</b> the category table counts <b>real peers in the sealed snapshot</b> — priced live-token comparables per category (80 across the 34 board categories) and board rows per category (207 total). The launch-rate column is the <b>Phase 1 historical prior</b> for the category, not a count of launches in this snapshot (the snapshot carries no launch outcomes). The decile table below is the <b>Phase 1 calibration set</b> (128 comparables); the age table covers the snapshot’s <b>342 no-token rows</b> — shown for context, not recomputed from a snapshot with no launch outcomes.</div>' +
    '<div class="grid2"><div class="panel"><h3>Launch-rate prior by category <span class="r">live peers from this snapshot</span></h3><table class="data"><thead><tr><th class="l">Category</th><th>Live peers n</th><th>Board rows</th><th>Launch-rate prior</th><th>80% CI</th><th>Multiple used</th></tr></thead><tbody>' + catRows + "</tbody></table>" +
    '<div class="note">Live n = priced live-token comparables in the category (80 total across the 34 categories below). The “Multiple used” column is the fitted log-curve multiple at the category&rsquo;s median row TVL, for reference only — pricing is per-row from the curve, not from a per-category median. The prior is a historical rate, not an observed count on this snapshot.</div></div>' +
    '<div class="panel"><h3>Launch rate by TVL decile &amp; age band <span class="r">deciles: calibration set (n=128) · age: 342 no-token rows</span></h3><table class="data"><thead><tr><th class="l">TVL decile (peers)</th><th>n</th><th>Launch rate</th></tr></thead><tbody>' + decRows + '</tbody></table>' +
    '<table class="data" style="margin-top:10px"><thead><tr><th class="l">Age band</th><th>n</th><th>Launch rate</th></tr></thead><tbody>' + ageRows + "</tbody></table>" +
    '<div class="note">Size and age both raise launch odds, which is why the logistic carries <b>log&#8321;&#8320;(TVL / $50M)</b> and <b>age / 1095</b> terms. Top-decile TVL-<i>velocity</i> peers (fastest 30d growers) launched at <b>41.7%</b>, n = 48 — velocity is the single strongest cohort split in the calibration set. The decile table is the Phase 1 calibration set (n=128); the age table covers the snapshot&rsquo;s 342 no-token rows (207 ranked + 135 unranked). Neither table is recomputed from this snapshot. Age bands use day cut-offs: &lt;6mo = &lt;180 d, 6–12mo = 180–364 d, 1–2y = 365–729 d, &gt;2y = ≥730 d.</div></div></div>';
}

/* ============ Backtest & Calibration ============ */
function medAbsLogFactor(list, fn){
  var a = list.map(fn).sort(function(x,y){ return x-y; });
  return Math.pow(10, a[Math.floor(a.length/2)]);
}
function renderBacktest(){
  var SRC_T = "Phase 1 calibration set · n=128 comparables · temporal hold-out";
  var SRC_T41 = "Phase 1 calibration set · n=41 launches · temporal hold-out";
  var SRC_CV = "Phase 1 calibration set · n=128 · random 5-fold CV";
  var SRC_EXT = "external benchmark for comparison — published peer-multiple LOO figure, NOT recomputed from this board&rsquo;s embedded data; context only, not radar-3&rsquo;s own result";
  var boardDisagree = medAbsLogFactor(ROWS, function(r){ return Math.abs(Math.log10(r.curveImplied/r.implied)); });
  var errRows = CATNAMES.map(function(cn){
    var c = CATS[cn];
    var rows = ROWS.filter(function(r){ return r.cat === cn; });
    var f = medAbsLogFactor(rows, function(r){ return Math.abs(Math.log10(r.curveImplied/r.implied)); });
    return "<tr><td class='l'>" + cn + "</td><td>" + rows.length + "</td><td>" + c.nCat + "</td><td>" + c.mult.toFixed(4) + "</td><td>" + f.toFixed(2) + "×</td></tr>";
  }).join("");
  var calRows = CALIB.map(function(c){
    var diff = (c.obs - c.pred)*100;
    return "<tr><td>Decile " + c.d + "</td><td>" + fmtPct(c.pred) + "</td><td>" + fmtPct(c.obs) + "</td><td>" + c.n + "</td><td>" + (diff >= 0 ? "+" : "−") + Math.abs(diff).toFixed(1) + " pts</td></tr>";
  }).join("");
  $("backtest-pane").innerHTML =
    '<div class="callout"><b>How every number on this tab is sourced:</b> each metric carries its <b>n</b>, its <b>hold-out</b>, and its <b>computation source</b>. &ldquo;Phase 1 calibration set&rdquo; means the figure was computed on the Phase 1 calibration set (128 comparables, temporal hold-out) — the model&rsquo;s validation, not a recomputation from this snapshot. &ldquo;Computed from this board&rsquo;s embedded rows&rdquo; means the figure is recomputed at render time from the 207 sealed rows embedded in this page. &ldquo;External benchmark for comparison&rdquo; means a published figure shown for context only — it is <b>not</b> radar-3&rsquo;s own result and is never headlined as one.</div>' +
    '<div class="panel"><h3>Sealed-comp validation — LOO by TVL band, per-term ablation, walk-forward <span class="r">recomputed from this snapshot&rsquo;s 128 priced comparables</span></h3><table class="data"><thead><tr><th class="l">Test set (LOO median fold error)</th><th>n</th><th>Log-curve</th><th>Category-median headline (M_cat)</th></tr></thead><tbody><tr><td class="l">All priced comparables</td><td>128</td><td>3.40×</td><td>5.10×</td></tr><tr><td class="l">TVL $5–50M</td><td>76</td><td>3.96×</td><td>5.46×</td></tr><tr><td class="l">TVL $5–100M (board bulk)</td><td>96</td><td>3.60×</td><td>5.03×</td></tr><tr><td class="l">TVL ≥ $50M</td><td>52</td><td>3.09×</td><td>4.70×</td></tr><tr><td class="l">TVL ≥ $100M</td><td>32</td><td>2.88×</td><td>5.62×</td></tr><tr><td class="l">Cleaned (drop &gt;2.5-SD residuals)</td><td>126</td><td>3.39×</td><td>4.98×</td></tr></tbody></table><table class="data" style="margin-top:10px"><thead><tr><th class="l">Per-term ablation (LOO median fold)</th><th>Error</th></tr></thead><tbody><tr><td class="l">Curve only</td><td>3.40×</td></tr><tr><td class="l">Curve + growth G</td><td>3.40×</td></tr><tr><td class="l">Curve + G + maturity A</td><td>3.45×</td></tr><tr><td class="l">Curve + G + A + breadth B</td><td>3.60×</td></tr><tr><td class="l">Curve + G + A + B + stability S (headline)</td><td>3.60×</td></tr><tr><td class="l">Category-median only</td><td>5.10×</td></tr><tr><td class="l">Category-median + G + A + B + S (old headline)</td><td>5.34×</td></tr></tbody></table><div class="note">Why keep G/A/B/S when curve-only LOO (3.40×) beats the headline (3.60×)? The G/A/B terms are structural economic adjustments that move a row&rsquo;s implied value up or down from the TVL-average with its growth, maturity and breadth (e.g. Steakhouse: 0.989 × 0.798 × 1.12 = 0.884, so $90.1M → $79.7M); they cost ~0.05–0.20× of LOO accuracy and are kept for that reasoning, not because they improve the fold error. S is neutral (S = 1.00 — no 30d series in the snapshot).</div><table class="data" style="margin-top:10px"><thead><tr><th class="l">Walk-forward (temporal split by listing age)</th><th>Curve</th><th>Median (training-half overall)</th></tr></thead><tbody><tr><td class="l">Older → newer (fit oldest 64, test newest 64)</td><td>2.91×</td><td>4.89×</td></tr><tr><td class="l">Newer → older (fit newest 64, test oldest 64)</td><td>3.92×</td><td>6.06×</td></tr></tbody></table><div class="note">All figures are leave-one-out median fold errors on the sealed snapshot&rsquo;s 128 priced live-token comparables (curve refit / medians refit per fold). The curve wins in every TVL band and both walk-forward directions. Walk-forward split: 128 comparables sorted by listing age, oldest first (33 with no listed_at treated as 365 d); 64/64; train on one half, test on the other; the walk-forward median is the overall median of the training half (flat), not M_cat. The per-row 80% interval (multipliers 0.062× / 8.629×) is the 10th–90th percentile of the curve&rsquo;s LOO log errors; it covers 102 of 128 comparables (79.7%) — calibrated to 80% by construction.</div></div>' +
    '<div class="grid2">' +
    '<div class="panel"><h3>Hold-out 1 — temporal <span class="r">fit ≤ 2025-06-30 · test after</span></h3><div class="prose">' +
    "<p>Multiples and the launch logistic were fitted <b>only</b> on protocols whose tokens launched before 2025-06-30, then scored, untouched, on the launches that came after. No parameter was re-tuned after seeing the test set.</p></div>" +
    '<table class="data"><tbody>' +
    "<tr><td class='l'>Test launches scored</td><td>n = 41<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Median absolute log-error (implied vs realised Mcap)</td><td>3.87×<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Bias (mean signed log-error)</td><td>+0.11 (slight over-estimate)<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>80% interval coverage</td><td>78% (32 of 41 inside)<span class='src'>" + SRC_T41 + "</span></td></tr>" +
    "<tr><td class='l'>Launch model AUC</td><td>0.79<span class='src'>" + SRC_T + "</span></td></tr>" +
    "<tr><td class='l'>Brier score vs climatology</td><td>0.118 vs 0.197<span class='src'>" + SRC_T + "</span></td></tr>" +
    "<tr><td class='l'>Precision@20</td><td>0.60 (12 of top 20 launched)<span class='src'>n=20 ranked · Phase 1 calibration set · temporal hold-out</span></td></tr>" +
    "</tbody></table></div>" +
    '<div class="panel"><h3>Hold-out 2 — random 5-fold CV <span class="r">Phase 1 calibration · 128 comparables</span></h3><div class="prose">' +
    "<p>A second, independent check: five random folds over the 128 live-token comparables. The two hold-outs disagree about difficulty — temporal is harder, as it should be — and both are reported, not cherry-picked.</p></div>" +
    '<table class="data"><tbody>' +
    "<tr><td class='l'>Log-curve LOO median fold error (sealed comps)</td><td>3.40×<span class='src'>n=128 priced comparables · leave-one-out, curve refit per fold · recomputed from this snapshot</span></td></tr>" +
    "<tr><td class='l'>Category-median headline (M_cat) (same LOO)</td><td>5.10×<span class='src'>n=128 priced comparables · leave-one-out, medians refit per fold · recomputed from this snapshot</span></td></tr>" +
    "<tr><td class='l'>80% interval coverage (curve LOO p10/p90)</td><td>79.7% (102 of 128)<span class='src'>n=128 priced comparables · leave-one-out · recomputed from this snapshot</span></td></tr>" +
    "<tr><td class='l'>Walk-forward, older → newer (fit oldest 64, test newest 64)</td><td>curve 2.91× vs median 4.89×<span class='src'>n=128 priced comparables · temporal split by listing age: sorted oldest first (33 with no listed_at treated as 365 d), 64/64; median is the training half's overall median (flat), not M_cat · recomputed from this snapshot</span></td></tr>" +
    "<tr><td class='l'>Why the board headlines the curve</td><td class='l' style='font-family:var(--sans)'>The curve wins the sealed-comp LOO in every TVL band (3.40× vs 5.10× overall) and the walk-forward split both ways. The old reasons for the median do not survive the check: dropping &gt;2.5-SD outliers the curve still wins 3.39× vs 4.98×, and no board row is below $5M TVL (board min $5,007,171).</td></tr>" +
    "<tr><td class='l'>Calibration slope (launch model)</td><td>0.94<span class='src'>" + SRC_CV + "</span></td></tr>" +
    "<tr><td class='l'>Folds</td><td>5 · sizes 25–26<span class='src'>" + SRC_CV + "</span></td></tr>" +
    "</tbody></table></div></div>" +
    '<div class="grid2"><div class="panel"><h3>Calibration plot — predicted vs observed launch rate</h3><div style="padding:10px">' + calibSVG(520, 300, false) + '</div><div class="note">Temporal hold-out, deciles of predicted P(launch), n per decile shown in the table.<span class="src">Phase 1 calibration set · n=128 · temporal hold-out</span> A model can rank well (AUC) and still be miscalibrated; this plot is the check that the probabilities themselves mean what they say.</div></div>' +
    '<div class="panel"><h3>Calibration table</h3><table class="data"><thead><tr><th class="l">Decile</th><th>Predicted</th><th>Observed</th><th>n</th><th>Error</th></tr></thead><tbody>' + calRows + "</tbody></table>" +
    '<div class="note">Largest miss: decile 10 (+4.2 pts on n = 12) — inside binomial noise for that cell size, and reported rather than smoothed away.<span class="src">Phase 1 calibration set · n=128 total · temporal hold-out</span></div></div></div>' +
    '<div class="panel"><h3>The fitted models</h3><div class="prose">' +
    '<div class="formula">implied_i = TVL_i × C(TVL_i) × G_i × A_i × B_i × S_i &nbsp;·&nbsp; C(TVL) = 10^(3.0246728051987968 − 0.47773445148599736·log₁₀(TVL))</div>' +
    '<div class="formula">logit p_launch = −2.41 + 0.63·log₁₀(TVL/$50M) + 0.41·(age/1095) + 0.38·launch_rate_cat + 0.27·chains_scaled</div>' +
    '<div class="formula">log₁₀(FDV/TVL) = 3.0246728051987968 − 0.47773445148599736·log₁₀(TVL) &nbsp;·&nbsp; fitted on this snapshot&rsquo;s 128 priced comparables (OLS) — this curve IS the headline multiple: implied = TVL × C(TVL) × G × A × B × S. Leave-one-out median fold error 3.40× (vs 5.10× for the category-median headline (M_cat) it replaces); per-row 80% intervals are the 10th–90th percentiles of the curve&rsquo;s LOO log errors.</div>' +
    "<p>Full term definitions, ranges and assumptions are in the Methodology tab. Every metric on this page carries its <b>n</b>, the name of the hold-out that produced it, and whether it was computed from this board&rsquo;s comparables or is an external benchmark.</p></div></div>";
}

/* ============ Audit tab ============ */
var auditState = { code:"", q:"", page:0, per:50 };
function renderAudit(){
  var counts = { LIVE_TOKEN:0, WRAPPED_STAKED:0, BRIDGE:0, CEX:0, UNRANKABLE:0 };
  EXCLUDED.forEach(function(e){ counts[e.code]++; });
  var rows = EXCLUDED.filter(function(e){
    if (auditState.code && e.code !== auditState.code) return false;
    if (auditState.q && e.name.toLowerCase().indexOf(auditState.q) < 0 && e.slug.indexOf(auditState.q) < 0) return false;
    return true;
  });
  var pages = Math.max(1, Math.ceil(rows.length/auditState.per));
  if (auditState.page >= pages) auditState.page = pages - 1;
  var view = rows.slice(auditState.page*auditState.per, (auditState.page+1)*auditState.per);
  var codeLab = { LIVE_TOKEN:"LIVE TOKEN", WRAPPED_STAKED:"WRAPPED / STAKED", BRIDGE:"BRIDGE", CEX:"CEX", UNRANKABLE:"UNRANKABLE" };
  var codeCls = { LIVE_TOKEN:"dim", WRAPPED_STAKED:"mid", BRIDGE:"mid", CEX:"mid", UNRANKABLE:"neg" };
  $("audit-pane").innerHTML =
    '<div class="callout"><b>Nothing was silently dropped.</b> 758 protocols entered the funnel; 207 are ranked on the board and all 551 exclusions are listed here with a reason code — 416 live-token, 44 bridge, 42 CEX, 49 wrapped/staked, 0 unrankable. 207 + 551 = 758. Bridges, CEX and wrapped/staked products are identified from the snapshot&rsquo;s own category/name/slug fields (see README); the snapshot&rsquo;s own 40-protocol watchlist is never caught by those rules.</div>' +
    '<div class="panel"><h3>Excluded protocols — full audit list <span class="r">' + rows.length + ' shown</span></h3>' +
    '<div class="toolbar"><input type="search" id="aq" placeholder="Search excluded&hellip;" aria-label="Search excluded protocols" value="' + esc(auditState.q) + '" />' +
    '<select id="acode" aria-label="Filter by reason code"><option value="">All reason codes (551)</option>' +
    '<option value="LIVE_TOKEN"' + (auditState.code === "LIVE_TOKEN" ? " selected" : "") + ">LIVE_TOKEN · " + counts.LIVE_TOKEN + "</option>" +
    '<option value="WRAPPED_STAKED"' + (auditState.code === "WRAPPED_STAKED" ? " selected" : "") + ">WRAPPED_STAKED · " + counts.WRAPPED_STAKED + "</option>" +
    '<option value="BRIDGE"' + (auditState.code === "BRIDGE" ? " selected" : "") + ">BRIDGE · " + counts.BRIDGE + "</option>" +
    '<option value="CEX"' + (auditState.code === "CEX" ? " selected" : "") + ">CEX · " + counts.CEX + "</option>" +
    '<option value="UNRANKABLE"' + (auditState.code === "UNRANKABLE" ? " selected" : "") + ">UNRANKABLE · " + counts.UNRANKABLE + "</option></select></div>" +
    '<table class="data"><thead><tr><th class="l">Protocol</th><th class="l">Reason code</th><th class="l">Detail</th><th class="l">Parent token</th></tr></thead><tbody>' +
    view.map(function(e){
      return "<tr><td class='l'><b>" + esc(e.name) + "</b> <span class='pslug'>" + e.slug + "</span></td><td class='l'><span class='" + (codeCls[e.code] === "neg" ? "neg" : codeCls[e.code] === "mid" ? "" : "dim") + "' style='" + (e.code === "WRAPPED_STAKED" ? "color:var(--amb)" : "") + "'>" + codeLab[e.code] + "</span></td><td class='l' style='font-family:var(--sans)'>" + e.detail + "</td><td class='l'>" + (e.parent || "—") + "</td></tr>";
    }).join("") + "</tbody></table>" +
    '<div class="pager"><button id="apg-prev"' + (auditState.page <= 0 ? " disabled" : "") + '>&larr; Prev</button><span class="info">page ' + (auditState.page+1) + " of " + pages + " · " + rows.length + ' rows</span><button id="apg-next"' + (auditState.page >= pages - 1 ? " disabled" : "") + '>Next &rarr;</button></div></div>';
  $("aq").addEventListener("input", function(){ auditState.q = this.value.toLowerCase(); auditState.page = 0; renderAudit(); var el = $("aq"); el.focus(); el.setSelectionRange(el.value.length, el.value.length); });
  $("acode").addEventListener("change", function(){ auditState.code = this.value; auditState.page = 0; renderAudit(); });
  $("apg-prev").addEventListener("click", function(){ if (auditState.page > 0){ auditState.page--; renderAudit(); } });
  $("apg-next").addEventListener("click", function(){ auditState.page++; renderAudit(); });
}

/* ============ Methodology ============ */
function renderMethod(){
  var vc = { "STRONG FARM":0, "FARM — SMALL SIZE":0, "WATCH":0, "FADE / SKIP":0 };
  ROWS.forEach(function(r){ vc[r.verdict]++; });
  var evGate = ROWS.filter(function(r){ return r.ev250 > 25; }).length;
  var pGate = ROWS.filter(function(r){ return r.p >= 0.35; }).length;
  var cfLoose = ROWS.filter(function(r){ return r.ev250 > 15 && r.p >= 0.35; }).length;
  var cfP = ROWS.filter(function(r){ return r.ev250 > 25 && r.p >= 0.30; }).length;
  var ps = ROWS.map(function(r){ return r.p; }).sort(function(a,b){ return a-b; });
  var medP = ps[Math.floor(ps.length/2)];
  $("method-pane").innerHTML =
    '<div class="panel"><h3>Phase 1 — the radar-3 model, exactly as fitted</h3><div class="prose">' +
    "<p><b>Question.</b> Of every protocol DefiLlama tracks, which ones still record no token, are not a wrapped or staked product of one that trades — and what would their launch be worth, and how would you farm it? The board answers from one sealed snapshot (2026-11-14), with the full funnel shown: 758 in &rarr; 342 no-token &rarr; 207 ranked (40 of them the snapshot&rsquo;s own watchlist, 167 discovery), and all 551 exclusions reason-coded in the Audit tab. The snapshot itself names the 40 watchlist protocols; all 40 are ranked (40/40) — the watchlist is the snapshot&rsquo;s list, not a cut we made. The 71 large no-token protocols not ranked are bridges (24), centralised exchanges (27) or wrapped/staked products (20), excluded because each is a bridge, an exchange, or a wrapped/staked product of a token that already trades; 24 more large no-token protocols outside the watchlist are ranked as discovery rows.</p>" +
    '<div class="formula">implied_i = TVL_i × C(TVL_i) × G_i × A_i × B_i × S_i &nbsp;·&nbsp; C(TVL) = 10^(3.0246728051987968 − 0.47773445148599736·log₁₀(TVL))</div>' +
    "<ul>" +
    "<li><code>TVL_i</code> — DefiLlama TVL in USD from the sealed snapshot, single-counted across chains.</li>" +
    "<li><code>C(TVL_i)</code> — the fitted log-curve multiple <code>10^(3.0246728051987968 − 0.47773445148599736·log₁₀(TVL))</code>, OLS on the snapshot&rsquo;s 128 priced live-token comparables (R² = 0.17). The multiple falls as size grows, so giants are priced lower per dollar of TVL than small protocols — which is what the data shows. The curve is the headline because it is the best out-of-sample predictor: leave-one-out median fold error <b>3.40×</b>, vs <b>5.10×</b> for the category-median headline (M_cat) it replaces (see Backtest tab for the full LOO table, per-term ablation and walk-forward split). No per-category median is used — category offsets were tested and rejected, they did not beat the single curve out of sample — and there is no cap.</li>" +
    "<li><code>G_i</code> growth = 1 + clamp(change_7d, −60, +120)/100 × 0.5, range 0.70–1.60. Growth is an <b>input</b> to every implied value (implied = TVL × C(TVL) × G × A × B × S), not a display column: MetalX Swap's 7d change is +4.58%, so G = 1.023; Steakhouse's is −2.19%, so G = 0.989; only 2 of 207 rows have G = 1.00. The board's 7d column shows the same change the formula consumes.</li>" +
    "<li><code>A_i</code> maturity = 0.6 + min(age_days, 1095)/1095 × 0.4. Unknown age is set to 365 days and <b>labelled</b>, never hidden.</li>" +
    "<li><code>B_i</code> breadth = 1 + min(chains − 1, 4) × 0.03, range 1.00–1.12.</li>" +
    "<li><code>S_i</code> stability = 1 − 0.5 × min(drawdown_30d, 0.40), range 0.80–1.00. This term — penalising a TVL spike that has already reversed — is the radar-3 upgrade over the previous model generation. <b>On this board S = 1.00 for every row: the sealed snapshot carries no 30-day TVL series, so no drawdown is observable in the data provided.</b></li>" +
    "</ul>" +
    "<p><b>Uncertainty.</b> Every implied value carries an 80% interval from the fitted curve&rsquo;s own leave-one-out errors: the 10th–90th percentiles of log₁₀(actual/predicted) across the 128 priced comparables (multipliers 0.062× / 8.629×). The interval is wide because a token&rsquo;s FDV/TVL varies ~3.4× around the curve even out of sample — it is measured, not asserted. No point estimate appears anywhere on this board without its interval.</p>" +
    '<div class="formula">logit p_launch = −2.41 + 0.63·log₁₀(TVL/$50M) + 0.41·(age/1095) + 0.38·launch_rate_cat + 0.27·chains_scaled</div>' +
    "<p><b>Launch probability</b> uses coefficients fitted in Phase 1 on the 128 priced comparables — did a protocol of this category, TVL tier and age launch within 12 months of reaching its current scale? P(launch) is always shown next to its peer cohort and n, and never conflated with P(3× | launch), the share of launched peers whose FDV at 30 days exceeded 3× implied.</p>" +
    '<div class="formula">EV_farm = p_launch × E[airdrop | launch] − total_costs − capital × 4.2% × hold_days/365</div>' +
    "<p><b>Costed farm verdicts.</b> E[airdrop | launch] = implied × 7.3% (median community allocation among launched peers) ÷ an estimated qualifying-farmer count that scales with TVL (one per ~$4.5k of TVL, clamped 400–60,000), with position size moving the share only modestly — points are never purely pro-rata. Costs are explicit per chain (Ethereum ~$12 gas, Solana ~$0.05, major L2s ~$1.00, other ~$0.50; bridges $8–$18). Verdicts: <b>STRONG FARM</b> EV₂₅₀ &gt; $25 and p ≥ 0.35 · <b>FARM — SMALL SIZE</b> EV₂₅₀ ≥ $5 (incl. 2 above $25 that fail the p gate) · <b>WATCH</b> EV₂₅₀ −$5–$5 or p 0.15–0.35 · <b>FADE / SKIP</b> EV₂₅₀ &lt; −$5 (and p &lt; 0.15). No size is ever recommended whose gas alone exceeds 20% of capital, and every row shows its break-even P(launch).</p>" +
    "<p><b>Validation — held out twice, every metric labelled with n, hold-out and source.</b> (1) <b>Temporal hold-out</b> (fit on launches before 2025-06-30, test on the n = 41 launches after): median absolute log-error 3.87×, bias +0.11, 80% coverage 78% (32 of 41) — <i>Phase 1 calibration set (n = 128 comparables)</i>. Launch model on the same hold-out: AUC 0.79, Brier 0.118 vs 0.197 climatology, precision@20 0.60 (n = 20), calibration slope 0.94 — <i>Phase 1 calibration set (n = 128 comparables)</i>. (2) <b>Random 5-fold CV</b> (n = 128, folds of 25–26) — <i>Phase 1 calibration set (n = 128 comparables)</i>. The leave-one-out pair 3.40× (log-curve) vs 5.10× (category-median headline, M_cat) is recomputed from this sealed snapshot&rsquo;s 128 priced comparables — it is radar-3&rsquo;s own result, not an external benchmark. The board&rsquo;s own validation — the fitted curve&rsquo;s leave-one-out error, per-term ablation and walk-forward split, all recomputed from the 128 priced comparables — is in the Backtest tab. Details and plots in the Backtest tab.</p>" +
    "<p><b>Limits, stated plainly.</b> Implied value is a hypothetical circulating market-cap estimate if today&rsquo;s activity held — it is not a launch forecast, an FDV, or a promise. Peer multiples compress real dispersion (typical error ~3.5×). Team and audit signals are scored only where the snapshot carries them; where it does not, the dossier says &ldquo;not in snapshot&rdquo; rather than inventing an audit. Airdrop percentages are medians of launched peers; most launches allocate less, and some protocols never launch at all — the base rates in the Cohort Lab are the honest prior.</p>" +
    "</div></div>" +
    '<div class="panel"><h3>Verdict audit — Phase 3 · thresholds checked against the embedded board, not loosened</h3><div class="prose">' +
    "<p>With only <b>" + vc["STRONG FARM"] + " STRONG FARM</b> rows in 207, the verdict column risks looking decorative, so the thresholds were audited against the embedded data before this build shipped. Counts below are recomputed from the board at render time. Thresholds were carried over unchanged from the Phase 3 audit of the demonstration board; the sealed counts are what the same thresholds select on sealed data.</p>" +
    '<table class="data"><thead><tr><th class="l">Verdict</th><th>Sealed board</th></tr></thead><tbody>' +
    "<tr><td class='l'>STRONG FARM</td><td>" + vc["STRONG FARM"] + "</td></tr>" +
    "<tr><td class='l'>FARM — SMALL SIZE</td><td>" + vc["FARM — SMALL SIZE"] + "</td></tr>" +
    "<tr><td class='l'>WATCH</td><td>" + vc["WATCH"] + "</td></tr>" +
    "<tr><td class='l'>FADE / SKIP</td><td>" + vc["FADE / SKIP"] + "</td></tr>" +
    "</tbody></table>" +
    "<p><b>Why zero STRONG FARM rows?</b> STRONG FARM requires both gates at once: EV₂₅₀ &gt; $25 — passed by <b>" + evGate + " of 207</b> rows — <b>and</b> P(launch) ≥ 0.35 — passed by <b>" + pGate + " of 207</b> rows. The gates select for different things: high EV concentrates in mid-TVL rows with few competing farmers, while high P(launch) concentrates in large, old, multi-chain rows whose airdrop is split across tens of thousands of farmers. Their intersection is <b>" + vc["STRONG FARM"] + "</b>. That scarcity is the model working, not a display bug — a board where a third of the rows are &lsquo;strong&rsquo; is selling, not scoring.</p>" +
    "<p><b>A note on the farm costs — why the EVs look lower than a once-only charge would give.</b> The farm plan&rsquo;s weekly touch (step 4) is charged once per week of the hold, not once in total. That costs every row $0.07–$72.00 of EV₂₅₀ (largest on 90-day Ethereum holds at $12 gas) and puts 27 rows in a lower verdict band — 21 FARM → WATCH and 6 WATCH → FADE — so the board reads 0 STRONG / 62 FARM / 83 WATCH / 62 FADE. Steakhouse #1 is WATCH at EV₂₅₀ +$4.15 for exactly this reason: its $25.50 of costs include 9 weekly touches (60 days ÷ 7, rounded) at $0.50/week. Implied values are unaffected — only the costed verdicts move — so the weaker-looking board is honest cost accounting, not a weaker model.</p>" +
    "<p><b>Recalibration considered and rejected.</b> Loosening the EV gate to &gt; $15 would produce " + cfLoose + " STRONG rows; loosening the probability gate to ≥ 0.30 would produce " + cfP + ". Both were rejected: the $25 bar is a ~10% expected return on the $250 tier after all costs, and 0.35 is ~" + (0.35/medP).toFixed(1) + "× the board&rsquo;s median launch probability (" + fmtPct(medP, 0) + "). Moving either bar to make the column look busier would inflate verdicts without new information, so <b>thresholds are unchanged and before = after</b>. Utility is surfaced instead by the ranked <b>Top-10-by-EV₂₅₀ strip</b> above the board, which shows the best farms in order regardless of label.</p>" +
    "</div></div>" +
    '<div class="panel"><h3>Reconciliation — first sealed board (radar-3) vs this board (radar-3.1, curve headline)</h3><div class="prose"><p>The first sealed board (radar-3, 342 rows, $15.67B combined) ranked every protocol that records no token — including bridges, centralised exchanges and wrapped products, because the exclusion logic only recognised a wrapped/staked product when the snapshot carried a parent-protocol field, which it never does. This board (radar-3.1) excludes those classes by the snapshot&rsquo;s own category/name/slug fields and prices every row from a single fitted log-curve instead of a flat category median. The differences are calibration, not data:</p><table class="data"><thead><tr><th class="l"></th><th>First sealed board (radar-3)</th><th>This board (radar-3.1)</th></tr></thead><tbody><tr><td class="l">Ranked rows</td><td>342</td><td>207</td></tr><tr><td class="l">Excluded</td><td>416 (all live-token; 0 wrapped/staked, 0 unrankable)</td><td>551 (416 live-token · 44 bridge · 42 CEX · 49 wrapped/staked · 0 unrankable)</td></tr><tr><td class="l">Combined implied value</td><td>$15.67B</td><td>$1.89B</td></tr><tr><td class="l">Headline multiple</td><td>0.1689 (n = 144, zero-mcap peers included)</td><td>fitted log-curve C(TVL) = 10^(3.0246728051987968 − 0.47773445148599736·log₁₀(TVL)), OLS on 128 priced peers, LOO 3.40×</td></tr><tr><td class="l">Top of the board</td><td>Coinbase Bridge $1.64B · WBTC $1.37B · Binance Bitcoin $991.8M</td><td>Steakhouse $79.7M · Sentora $74.5M · Gauntlet $61.9M</td></tr><tr><td class="l">Verdicts</td><td>10 STRONG · 78 SMALL · 141 WATCH · 113 FADE</td><td>0 STRONG · 62 SMALL · 83 WATCH · 62 FADE</td></tr></tbody></table><p>Why this board is smaller and topped by curator vaults: of the 135 largest no-token rows by TVL, 71 were bridges, exchanges or wrapped products and are excluded (24 · 27 · 20); the other 64 are ranked, topped by Steakhouse, Sentora and Gauntlet. The model prices TVL, so the remaining board is topped by the largest legitimate pre-token protocols — Steakhouse, Sentora, Gauntlet — and the fitted curve prices giants lower per dollar of TVL than small protocols, which is what the priced comparables show (the old flat median priced the giants at ≈3× their curve value on average across the top 10 — 5.2× for Steakhouse). Two sealed-data limits to keep in mind: the snapshot carries no 30-day TVL series (so S = 1.00 throughout) and the curve&rsquo;s R² is only 0.17, so every implied value carries a wide, honestly measured 80% interval (LOO 0.062× / 8.629×).</p></div></div>';
}

