/* ============ Recompute sandbox (J5) — the same code path as the board ============ */
function sandboxRow(){
  var tvl = parseFloat($("sb-tvl").value);
  var chg7 = parseFloat($("sb-chg7").value);
  var age = parseFloat($("sb-age").value);
  var chains = parseInt($("sb-chains").value, 10);
  var cat = $("sb-cat").value;
  var chain = $("sb-chain").value;
  if (!isFinite(tvl) || tvl <= 0) tvl = 100000000;
  if (!isFinite(chg7)) chg7 = 0;
  if (!isFinite(chains) || chains < 1) chains = 1;
  if (chains > 12) chains = 12;
  var ageKnown = isFinite(age);
  var ageEff = ageKnown ? age : 365;
  var G = 1 + clamp(chg7, -60, 120) / 100 * 0.5;
  var A = 0.6 + Math.min(ageEff, 1095) / 1095 * 0.4;
  var B = 1 + Math.min(chains - 1, 4) * 0.03;
  var S = 1.00;
  var cm = curveMult(tvl);
  var implied = tvl * cm * G * A * B * S;
  var c = CATS[cat] || { launchRate: 0.22, nCat: 0 };
  var LOGIT = { intercept: -2.41, tvl: 0.63, age: 0.41, launchRate: 0.38, chains: 0.27 };
  var logitP = LOGIT.intercept + LOGIT.tvl * Math.log10(tvl / 50e6)
    + LOGIT.age * (ageEff / 1095) + LOGIT.launchRate * c.launchRate
    + LOGIT.chains * (Math.min(chains - 1, 4) / 4);
  var p = logistic(logitP);
  var seL = 0.34 + 0.55 / Math.sqrt(Math.max(c.nCat, 1) * 9);
  var pLo = logistic(logitP - 1.2816 * seL), pHi = logistic(logitP + 1.2816 * seL);
  var chainArr = [];
  for (var i = 0; i < chains; i++) chainArr.push(chain);
  var r = { name: "Sandbox", cat: cat, chains: chainArr, mainChain: chain,
    bridge: chains > 1 ? 4 + Math.min(14, chains * 2) : 0,
    tvl: tvl, chg7: chg7, age: ageEff, ageKnown: ageKnown, p: p, implied: implied };
  var evs = [50, 250, 1000].map(function(sz){ return { sz: sz, e: evAt(r, sz) }; });
  return { tvl: tvl, chg7: chg7, ageEff: ageEff, ageKnown: ageKnown, chains: chains, cat: cat, chain: chain,
    cm: cm, G: G, A: A, B: B, S: S, implied: implied, lo: implied * LOO_LO_MULT, hi: implied * LOO_HI_MULT,
    p: p, pLo: pLo, pHi: pHi, evs: evs, hold: farmPlan(r).hold };
}
function renderSandbox(){
  var catOpts = CATNAMES.map(function(cn){ return '<option value="' + esc(cn) + '">' + esc(cn) + '</option>'; }).join("");
  var chainSeen = {};
  Object.keys(GAS).forEach(function(g){ chainSeen[g] = true; });
  ROWS.forEach(function(r){ chainSeen[r.mainChain] = true; });
  var chainOpts = Object.keys(chainSeen).map(function(g){ return '<option value="' + esc(g) + '">' + esc(g) + '</option>'; }).join("");
  $("sandbox-panel").innerHTML =
    '<h3>Recompute sandbox — the same formula, your inputs <span class="r">implied = TVL × C(TVL) × G × A × B × S · EV via the board&rsquo;s own evAt</span></h3>' +
    '<div class="sandbox">' +
    '<label>TVL (USD)<input type="number" id="sb-tvl" min="1" step="1000"></label>' +
    '<label>7d TVL change (%)<input type="number" id="sb-chg7" step="0.1"></label>' +
    '<label>Age (days, blank → 365)<input type="number" id="sb-age" min="0" step="1"></label>' +
    '<label>Chains (count)<input type="number" id="sb-chains" min="1" max="12" step="1"></label>' +
    '<label>Category<select id="sb-cat">' + catOpts + '</select></label>' +
    '<label>Main chain (gas)<select id="sb-chain">' + chainOpts + '</select></label>' +
    '<button id="sb-preset-steak" type="button">Preset: Steakhouse (#1)</button>' +
    '<button id="sb-preset-metalx" type="button">Preset: MetalX (best EV)</button>' +
    '<div class="sb-out" id="sb-out"></div>' +
    '</div>' +
    '<div class="note">Same code path as the board; no second formula. S = 1.00 throughout. Logit: −2.41 + 0.63·log₁₀(TVL/$50M) + 0.41·(age/1095) + 0.38·launch_rate_cat + 0.27·chains_scaled.</div>';
  function renderSandboxOut(){
    var s = sandboxRow();
    window.SANDBOX_LAST = s;
    var evBits = s.evs.map(function(x){
      return 'EV $' + x.sz + ' <b id="sb-ev' + x.sz + '">' + fmtSigned(x.e.ev) + '</b>';
    }).join(" · ");
    $("sb-out").innerHTML =
      'C(TVL) <b id="sb-curve">' + s.cm.toFixed(4) + '</b> · G <b id="sb-g">' + s.G.toFixed(3) + '</b> · A <b id="sb-a">' + s.A.toFixed(3) + '</b> · B <b id="sb-b">' + s.B.toFixed(2) + '</b> · S <b>1.00</b> → ' +
      '<b>Implied <span id="sb-implied">' + fmtUSD(s.implied) + '</span></b> · 80% CI <span id="sb-ci">' + fmtUSD(s.lo) + ' – ' + fmtUSD(s.hi) + '</span> · ' +
      'P(launch) <b id="sb-p">' + fmtPct(s.p) + '</b> · ' + evBits + ' · cap. charge <b>' + fmtUSDfull(s.evs[1].e.opp) + '</b>';
  }
  function preset(slug){
    var r = bySlug[slug];
    if (!r) return;
    $("sb-tvl").value = r.tvl;
    $("sb-chg7").value = r.chg7;
    $("sb-age").value = r.ageKnown ? r.age : "";
    $("sb-chains").value = r.chains.length;
    $("sb-cat").value = r.cat;
    $("sb-chain").value = r.mainChain;
    renderSandboxOut();
  }
  ["sb-tvl", "sb-chg7", "sb-age", "sb-chains", "sb-cat", "sb-chain"].forEach(function(id){
    $(id).addEventListener("input", renderSandboxOut);
    $(id).addEventListener("change", renderSandboxOut);
  });
  $("sb-preset-steak").addEventListener("click", function(){ preset("steakhouse-financial"); });
  $("sb-preset-metalx").addEventListener("click", function(){ preset("metalx-swap"); });
  preset("steakhouse-financial");
}
